use std::cell::RefCell;
use std::rc::Rc;
impl Solution {
    pub fn get_all_elements(
        root1: Option<Rc<RefCell<TreeNode>>>,
        root2: Option<Rc<RefCell<TreeNode>>>,
    ) -> Vec<i32> {
        let mut a = Vec::new();
        let mut b = Vec::new();

        Solution::dfs(&root1, &mut a);
        Solution::dfs(&root2, &mut b);

        let mut ans = Vec::new();
        let (mut i, mut j) = (0, 0);

        while i < a.len() && j < b.len() {
            if a[i] <= b[j] {
                ans.push(a[i]);
                i += 1;
            } else {
                ans.push(b[j]);
                j += 1;
            }
        }

        while i < a.len() {
            ans.push(a[i]);
            i += 1;
        }

        while j < b.len() {
            ans.push(b[j]);
            j += 1;
        }

        ans
    }

    fn dfs(root: &Option<Rc<RefCell<TreeNode>>>, nums: &mut Vec<i32>) {
        if let Some(node) = root {
            let node = node.borrow();
            Solution::dfs(&node.left, nums);
            nums.push(node.val);
            Solution::dfs(&node.right, nums);
        }
    }
}

package io.github.leetcode.tree;

import io.github.leetcode.tree.TreeNodes.TreeNode;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class AllElementsInTwoBinarySearchTrees {

    public List<Integer> getAllElements(TreeNode root1, TreeNode root2) {
        List<Integer> list1 = new ArrayList<>();
        getInorder(root1, list1);
        List<Integer> list2 = new ArrayList<>();
        getInorder(root2, list2);

        return mergeLists(list1, list2);
    }

    public List<Integer> mergeLists(List<Integer> list1, List<Integer> list2) {
        list2.addAll(list1);
        Collections.sort(list2);
        return list2;
    }

    public void getInorder(TreeNode root, List<Integer> list) {
        if (root == null) return;

        getInorder(root.left, list);
        list.add(root.val);
        getInorder(root.right, list);
    }

}

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    void getNodes(TreeNode* root, vector<int> &ans){
        if(root == NULL)
            return;

        ans.push_back(root->val);
        getNodes(root->left, ans);
        getNodes(root->right, ans);
    } 

    vector<int> getAllElements(TreeNode* root1, TreeNode* root2) {
        vector<int> ans;
        getNodes(root1, ans);
        getNodes(root2, ans);
        sort(ans.begin(), ans.end());
        return ans;
    }
};

